/** Wordmark. O símbolo é opcional — o hub usa com, o toggle usa sem. */
export function AnankMark({
  className,
  withSymbol = false,
}: {
  className?: string;
  withSymbol?: boolean;
}) {
  return (
    <span className={cn('inline-flex items-center gap-2', className)}>
      {withSymbol ? <AnankSymbol className="size-[1em] text-[color:var(--brand-accent)]" /> : null}
      <span className="font-display font-light tracking-[0.18em] uppercase">Anank Studios</span>
    </span>
  );
}

/** Ícone de grid 2×2 — volta para o hub. */
export function GridIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 16 16"
      width="14"
      height="14"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      aria-hidden="true"
      className={className}
    >
      <rect x="1.5" y="1.5" width="5" height="5" />
      <rect x="9.5" y="1.5" width="5" height="5" />
      <rect x="1.5" y="9.5" width="5" height="5" />
      <rect x="9.5" y="9.5" width="5" height="5" />
    </svg>
  );
}
